-- Brixora schema for MySQL 8 / MariaDB 10.6+ (Hostinger). See SPEC.md §7, §11.
--
-- Security model: the database user belongs to the Next.js
-- server only and is never exposed to browsers. Every page, server action and route
-- handler authorises the caller first (requireAdmin / requireOwner + ownership check),
-- and public reads go through the public_* views, which expose only safe columns of
-- live listings.
--
-- All timestamps are UTC (the app sets time_zone = '+00:00' on every connection).
-- IDs are UUID strings generated by the app.
--
-- Apply once:  mysql -h HOST -u USER -p DBNAME < db/schema.sql
-- then every file in db/migrations, in order.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- ---------------------------------------------------------------------------
-- App config: ref_prefix, ref_seq (reference number counter), listing_expiry_days.
-- ---------------------------------------------------------------------------
CREATE TABLE app_config (
  name  VARCHAR(64)  NOT NULL PRIMARY KEY,
  value VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO app_config (name, value) VALUES
  ('ref_prefix', 'BRX'),
  ('ref_seq', '0'),
  ('listing_expiry_days', '90');

-- ---------------------------------------------------------------------------
-- Users: owners (phone, WhatsApp OTP) and the admin (email + password + TOTP).
-- Admin accounts are created only by scripts/create-admin.mjs; there is no sign-up.
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id                CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  role              ENUM('admin', 'owner') NOT NULL DEFAULT 'owner',
  name              VARCHAR(80)  NULL,
  phone             VARCHAR(20)  CHARACTER SET ascii NULL,  -- digits with country code, e.g. 919876543210
  phone_verified_at DATETIME(3)  NULL,
  email             VARCHAR(254) NULL,
  password_hash     VARCHAR(255) CHARACTER SET ascii NULL,  -- scrypt$N$r$p$salt$hash
  totp_secret       VARCHAR(255) CHARACTER SET ascii NULL,  -- AES-256-GCM encrypted base32 secret
  totp_enabled      TINYINT(1)   NOT NULL DEFAULT 0,
  totp_last_step    BIGINT       NULL,                      -- last accepted TOTP step (replay guard)
  wa_opt_out        TINYINT(1)   NOT NULL DEFAULT 0,
  created_at        DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY users_phone_uq (phone),
  UNIQUE KEY users_email_uq (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Sessions. The cookie holds a random token; only its SHA-256 is stored here, so a
-- leaked table can't be replayed as cookies.
CREATE TABLE sessions (
  id           CHAR(64)    CHARACTER SET ascii NOT NULL PRIMARY KEY,  -- sha256(token) hex
  user_id      CHAR(36)    CHARACTER SET ascii NOT NULL,
  kind         ENUM('owner', 'admin') NOT NULL,
  mfa_verified TINYINT(1)  NOT NULL DEFAULT 0,
  ip           VARCHAR(64) NULL,
  user_agent   VARCHAR(255) NULL,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at   DATETIME(3) NOT NULL,
  KEY sessions_user_idx (user_id),
  KEY sessions_expires_idx (expires_at),
  CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- WhatsApp login codes. Stored as an HMAC, never in plain text.
CREATE TABLE otp_codes (
  id          CHAR(36)    CHARACTER SET ascii NOT NULL PRIMARY KEY,
  phone       VARCHAR(20) CHARACTER SET ascii NOT NULL,
  code_hash   CHAR(64)    CHARACTER SET ascii NOT NULL,
  attempts    INT         NOT NULL DEFAULT 0,
  consumed_at DATETIME(3) NULL,
  expires_at  DATETIME(3) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY otp_codes_phone_idx (phone, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Rate-limit ledger for sign-in attempts (admin password, TOTP, OTP send/verify).
CREATE TABLE auth_attempts (
  id         BIGINT      NOT NULL AUTO_INCREMENT PRIMARY KEY,
  kind       VARCHAR(20) CHARACTER SET ascii NOT NULL,  -- admin_password | admin_totp | otp_send | otp_verify
  identifier VARCHAR(254) NOT NULL,                     -- email, phone or user id
  ip         VARCHAR(64) NULL,
  success    TINYINT(1)  NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY auth_attempts_ident_idx (kind, identifier, created_at),
  KEY auth_attempts_ip_idx (kind, ip, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Builders & projects
-- ---------------------------------------------------------------------------
CREATE TABLE builders (
  id           CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  name         VARCHAR(160) NOT NULL,
  rera_no      VARCHAR(80)  NULL,
  contact_name VARCHAR(120) NULL,
  phone        VARCHAR(20)  NULL,
  notes        TEXT         NULL,
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE projects (
  id         CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  builder_id CHAR(36)     CHARACTER SET ascii NOT NULL,
  name       VARCHAR(160) NOT NULL,
  locality   VARCHAR(80)  NULL,
  rera_no    VARCHAR(80)  NULL,
  status     ENUM('upcoming', 'under_construction', 'ready') NOT NULL DEFAULT 'under_construction',
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY projects_builder_idx (builder_id),
  CONSTRAINT projects_builder_fk FOREIGN KEY (builder_id) REFERENCES builders (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Properties
-- ---------------------------------------------------------------------------
CREATE TABLE properties (
  id                  CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  reference_no        VARCHAR(40)  NOT NULL,
  status              ENUM('draft', 'pending', 'under_review', 'approved', 'rejected',
                           'sold_pending', 'sold', 'archived', 'expired') NOT NULL DEFAULT 'draft',
  listing_type        ENUM('sale', 'rent') NOT NULL,
  property_type       ENUM('apartment', 'villa', 'independent_house', 'plot',
                           'commercial', 'office', 'shop', 'warehouse') NOT NULL,
  title               VARCHAR(160) NOT NULL,
  description         TEXT         NULL,
  price               BIGINT       NOT NULL,
  price_negotiable    TINYINT(1)   NOT NULL DEFAULT 0,
  locality            VARCHAR(80)  NOT NULL,
  city                VARCHAR(60)  NOT NULL,
  private_address     VARCHAR(300) NULL,
  private_landmark    VARCHAR(200) NULL,
  bedrooms            SMALLINT     NULL,
  bathrooms           SMALLINT     NULL,
  area_sqft           INT          NULL,
  furnishing          ENUM('unfurnished', 'semi_furnished', 'fully_furnished') NULL,
  floor               VARCHAR(40)  NULL,
  property_age        VARCHAR(40)  NULL,
  available_from      DATE         NULL,
  amenities           JSON         NOT NULL,
  builder_id          CHAR(36)     CHARACTER SET ascii NULL,
  project_id          CHAR(36)     CHARACTER SET ascii NULL,
  rera_no             VARCHAR(80)  NULL,
  featured            TINYINT(1)   NOT NULL DEFAULT 0,
  owner_id            CHAR(36)     CHARACTER SET ascii NOT NULL,
  submitted_at        DATETIME(3)  NULL,
  reviewed_by         CHAR(36)     CHARACTER SET ascii NULL,
  approved_at         DATETIME(3)  NULL,
  rejected_reason     TEXT         NULL,
  sold_at             DATETIME(3)  NULL,
  expires_at          DATETIME(3)  NULL,
  original_submission JSON         NULL,
  internal_notes      TEXT         NULL,
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY properties_reference_uq (reference_no),
  KEY properties_status_idx (status),
  KEY properties_owner_idx (owner_id),
  KEY properties_public_idx (status, locality, listing_type, property_type, price),
  KEY properties_expiry_idx (status, expires_at),
  CONSTRAINT properties_price_chk CHECK (price > 0),
  CONSTRAINT properties_bedrooms_chk CHECK (bedrooms IS NULL OR bedrooms >= 0),
  CONSTRAINT properties_bathrooms_chk CHECK (bathrooms IS NULL OR bathrooms >= 0),
  CONSTRAINT properties_area_chk CHECK (area_sqft IS NULL OR area_sqft > 0),
  CONSTRAINT properties_builder_fk FOREIGN KEY (builder_id) REFERENCES builders (id) ON DELETE SET NULL,
  CONSTRAINT properties_project_fk FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL,
  CONSTRAINT properties_owner_fk FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE RESTRICT,
  CONSTRAINT properties_reviewer_fk FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Change requests
-- ---------------------------------------------------------------------------
CREATE TABLE change_requests (
  id           CHAR(36)    CHARACTER SET ascii NOT NULL PRIMARY KEY,
  property_id  CHAR(36)    CHARACTER SET ascii NOT NULL,
  type         ENUM('price', 'details', 'sold') NOT NULL,
  proposed     JSON        NOT NULL,
  status       ENUM('pending', 'approved', 'rejected') NOT NULL DEFAULT 'pending',
  requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  submitted    TINYINT(1)  NOT NULL DEFAULT 0,  -- 1 once the owner finished (photos uploaded)
  reviewed_by  CHAR(36)    CHARACTER SET ascii NULL,
  reviewed_at  DATETIME(3) NULL,
  admin_note   TEXT        NULL,
  KEY change_requests_property_idx (property_id),
  KEY change_requests_status_idx (status, submitted),
  CONSTRAINT change_requests_property_fk FOREIGN KEY (property_id) REFERENCES properties (id) ON DELETE CASCADE,
  CONSTRAINT change_requests_reviewer_fk FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Images. storage_path = original (private), watermarked_path = public WebP.
-- ---------------------------------------------------------------------------
CREATE TABLE property_images (
  id                CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  property_id       CHAR(36)     CHARACTER SET ascii NOT NULL,
  storage_path      VARCHAR(255) NOT NULL,
  watermarked_path  VARCHAR(255) NOT NULL,
  sort_order        INT          NOT NULL DEFAULT 0,
  is_cover          TINYINT(1)   NOT NULL DEFAULT 0,
  is_visible        TINYINT(1)   NOT NULL DEFAULT 1,
  approved          TINYINT(1)   NOT NULL DEFAULT 0,
  change_request_id CHAR(36)     CHARACTER SET ascii NULL,
  uploaded_by       CHAR(36)     CHARACTER SET ascii NULL,
  created_at        DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY property_images_property_idx (property_id, sort_order),
  KEY property_images_request_idx (change_request_id),
  CONSTRAINT property_images_property_fk FOREIGN KEY (property_id) REFERENCES properties (id) ON DELETE CASCADE,
  CONSTRAINT property_images_request_fk FOREIGN KEY (change_request_id) REFERENCES change_requests (id) ON DELETE CASCADE,
  CONSTRAINT property_images_uploader_fk FOREIGN KEY (uploaded_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Enquiries
-- ---------------------------------------------------------------------------
CREATE TABLE enquiries (
  id            CHAR(36)    CHARACTER SET ascii NOT NULL PRIMARY KEY,
  property_id   CHAR(36)    CHARACTER SET ascii NULL,
  name          VARCHAR(80) NOT NULL,
  phone         VARCHAR(20) NOT NULL,
  message       TEXT        NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  forwarded     TINYINT(1)  NOT NULL DEFAULT 0,
  forward_error TEXT        NULL,
  KEY enquiries_created_idx (created_at),
  CONSTRAINT enquiries_property_fk FOREIGN KEY (property_id) REFERENCES properties (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- WhatsApp message log
-- ---------------------------------------------------------------------------
CREATE TABLE messages (
  id              CHAR(36)     CHARACTER SET ascii NOT NULL PRIMARY KEY,
  recipient_phone VARCHAR(20)  CHARACTER SET ascii NOT NULL,
  template_name   VARCHAR(64)  NOT NULL,
  payload         JSON         NOT NULL,
  wa_message_id   VARCHAR(128) NULL,
  status          ENUM('queued', 'sent', 'delivered', 'read', 'failed') NOT NULL DEFAULT 'queued',
  error           TEXT         NULL,
  attempts        INT          NOT NULL DEFAULT 0,
  enquiry_id      CHAR(36)     CHARACTER SET ascii NULL,
  created_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY messages_recipient_idx (recipient_phone, template_name, created_at),
  KEY messages_wa_id_idx (wa_message_id),
  KEY messages_status_idx (status),
  KEY messages_enquiry_idx (enquiry_id),
  CONSTRAINT messages_enquiry_fk FOREIGN KEY (enquiry_id) REFERENCES enquiries (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Activity log
-- ---------------------------------------------------------------------------
CREATE TABLE activity_log (
  id          CHAR(36)    CHARACTER SET ascii NOT NULL PRIMARY KEY,
  entity_type VARCHAR(32) NOT NULL,
  entity_id   CHAR(36)    CHARACTER SET ascii NOT NULL,
  action      VARCHAR(64) NOT NULL,
  actor_type  ENUM('admin', 'owner', 'system') NOT NULL,
  actor_id    CHAR(36)    CHARACTER SET ascii NULL,
  diff        JSON        NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY activity_log_entity_idx (entity_type, entity_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Public views: safe columns of live listings only. Listings past expires_at drop out
-- immediately, even before the daily expiry job flips their status.
-- ---------------------------------------------------------------------------
CREATE VIEW public_properties AS
SELECT
  p.id,
  p.reference_no,
  p.listing_type,
  p.property_type,
  p.title,
  p.description,
  p.price,
  p.price_negotiable,
  p.locality,
  p.city,
  p.bedrooms,
  p.bathrooms,
  p.area_sqft,
  p.furnishing,
  p.floor,
  p.property_age,
  p.available_from,
  p.amenities,
  p.rera_no,
  p.featured,
  p.approved_at,
  p.updated_at,
  b.name AS builder_name,
  b.rera_no AS builder_rera_no,
  pr.name AS project_name,
  pr.rera_no AS project_rera_no,
  (
    SELECT i.watermarked_path
    FROM property_images i
    WHERE i.property_id = p.id AND i.is_visible = 1 AND i.approved = 1
    ORDER BY i.is_cover DESC, i.sort_order, i.created_at
    LIMIT 1
  ) AS cover_path
FROM properties p
LEFT JOIN builders b ON b.id = p.builder_id
LEFT JOIN projects pr ON pr.id = p.project_id
WHERE p.status = 'approved' AND (p.expires_at IS NULL OR p.expires_at > UTC_TIMESTAMP(3));

CREATE VIEW public_images AS
SELECT
  i.id,
  i.property_id,
  i.watermarked_path,
  i.sort_order,
  i.is_cover
FROM property_images i
JOIN properties p ON p.id = i.property_id
WHERE p.status = 'approved' AND (p.expires_at IS NULL OR p.expires_at > UTC_TIMESTAMP(3))
  AND i.is_visible = 1 AND i.approved = 1;
